[CmdletBinding()]
param([switch]$NoShow)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Windows.Forms
$script:appRoot=Split-Path -Parent $MyInvocation.MyCommand.Path
. (Join-Path $script:appRoot 'Core.Git.ps1');. (Join-Path $script:appRoot 'Core.FileOps.ps1');. (Join-Path $script:appRoot 'Core.SqlPlus.ps1')
[xml]$xaml=Get-Content -LiteralPath (Join-Path $script:appRoot 'UI.xaml') -Raw -Encoding UTF8
$window=[Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xaml))
$names=@('InlineStatus','Step1Button','Step2Button','Step3Button','CollectView','ReviewView','DeliverView','ChooseFilesButton','ChooseFolderButton','CollectProgress','CollectHint','AdvancedCollect','ExcludeRules','PasteInput','AddPathsButton','PasteResult','RepoPath','ChooseRepoButton','BaseBranch','CompareBranch','LoadBranchesButton','AddGitChangesButton','IncludeWorkspace','GitHint','ReviewSummary','SearchBox','FilterBox','EmptyState','FileGrid','ToggleFilteredButton','SelectAllButton','ClearSelectionButton','RemoveSelectedButton','ContinueButton','DeliverTitle','DeliverSummary','DestinationPath','ChooseDestinationButton','DestinationError','BackToReviewButton','DuplicateMode','VerifyHash','SqlOptions','CreateRunScript','SqlSettingsLine','ConfigureSqlButton','SqlConfigError','DeliveryProgress','DeliveryStatus','StartDeliveryButton','CancelDeliveryButton','DeliveryOptions','ResultPanel','ResultTitle','ResultSummary','OpenDestinationButton','OpenManifestButton','ReviewErrorsButton')
foreach($name in $names){Set-Variable -Name $name -Value $window.FindName($name) -Scope Script}
$script:items=New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$script:viewItems=New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$script:knownSources=New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
$script:db=[pscustomobject]@{User='HOSTBVSFUND';Password='';Tns='FLEX_236';Log='../log/install.log'}
$FileGrid.ItemsSource=$script:viewItems
[Windows.Controls.ToolTipService]::SetShowOnDisabled($Step2Button,$true);[Windows.Controls.ToolTipService]::SetShowOnDisabled($Step3Button,$true)

function Set-Status([string]$Text,[string]$Color='#1463D6'){$InlineStatus.Text=$Text;$InlineStatus.Foreground=[Windows.Media.BrushConverter]::new().ConvertFromString($Color)}
function Get-SelectedItems{return @($script:items|Where-Object Included)}
function Get-FileType([string]$Path){$ext=[IO.Path]::GetExtension($Path).TrimStart('.');if(-not $ext){return 'Other'};return $ext.ToUpperInvariant()}
function Convert-UiStatus([string]$Status){if($Status -match '^Ready'){return 'Ready'};if($Status -match '^Git'){return 'Git change'};if($Status -match '^Copied and verified'){return 'Copied and verified'};if($Status -match '^Copied'){return 'Copied'};if($Status -match '^Skipped'){return 'Skip'};if($Status -match '^Cancelled'){return 'Cancelled'};if($Status -match '^(Error|Failed)'){return 'Error: '+($Status -replace '^(Error|Failed):?\s*','')};return $Status}
function Set-Step([int]$Step){$CollectView.Visibility=if($Step -eq 1){'Visible'}else{'Collapsed'};$ReviewView.Visibility=if($Step -eq 2){'Visible'}else{'Collapsed'};$DeliverView.Visibility=if($Step -eq 3){'Visible'}else{'Collapsed'};foreach($pair in @(@($Step1Button,1),@($Step2Button,2),@($Step3Button,3))){$pair[0].Background=if($pair[1] -eq $Step){[Windows.Media.Brushes]::AliceBlue}else{[Windows.Media.Brushes]::Transparent};$pair[0].Foreground=if($pair[1] -eq $Step){[Windows.Media.BrushConverter]::new().ConvertFromString('#1463D6')}else{[Windows.Media.BrushConverter]::new().ConvertFromString('#28384D')}}}
function Update-Ui {
 $selected=@(Get-SelectedItems);[long]$bytes=0;foreach($i in $selected){$bytes+=[long]$i.Size};$sql=(@($selected|Where-Object {[IO.Path]::GetExtension($_.Relative).Equals('.sql',[StringComparison]::OrdinalIgnoreCase)})).Count
 $Step2Button.IsEnabled=($script:items.Count -gt 0);$Step2Button.Content="2  Review ($($script:items.Count))";$Step3Button.IsEnabled=($selected.Count -gt 0)
 $ReviewSummary.Text="$($script:items.Count) file | $($selected.Count) selected | $(Format-DeliverySize $bytes) | $sql SQL";$ContinueButton.Content="Continue ($($selected.Count) file)";$ContinueButton.IsEnabled=($selected.Count -gt 0)
 $DeliverTitle.Text="Deliver $($selected.Count) file | $(Format-DeliverySize $bytes)";$DeliverSummary.Text='Select a destination folder, then start delivery.';$SqlOptions.Visibility=if($sql){'Visible'}else{'Collapsed'};$EmptyState.Visibility=if($script:items.Count){'Collapsed'}else{'Visible'}
 Refresh-Grid
}
function Refresh-Grid {
 $query=$SearchBox.Text.Trim();$filter=if($FilterBox.SelectedItem){$FilterBox.SelectedItem.Content}else{'All'};$script:viewItems.Clear()
 foreach($item in $script:items){$ok=([string]::IsNullOrWhiteSpace($query) -or $item.FileName.IndexOf($query,[StringComparison]::OrdinalIgnoreCase)-ge 0 -or $item.Source.IndexOf($query,[StringComparison]::OrdinalIgnoreCase)-ge 0 -or $item.Relative.IndexOf($query,[StringComparison]::OrdinalIgnoreCase)-ge 0);if($ok){switch($filter){'Selected'{$ok=$item.Included};'Not selected'{$ok=-not $item.Included};'SQL'{$ok=[IO.Path]::GetExtension($item.Relative).Equals('.sql',[StringComparison]::OrdinalIgnoreCase)};'Errors'{$ok=$item.Status -match 'Error|Failed'}}};if($ok){[void]$script:viewItems.Add($item)}}
 $ToggleFilteredButton.IsChecked=($script:viewItems.Count -gt 0 -and @($script:viewItems|Where-Object {-not $_.Included}).Count -eq 0);$FileGrid.Items.Refresh()
}
function Add-Items([object[]]$Files,[hashtable]$GitStatus=@{}) {
 $added=0;$duplicates=0;foreach($file in $Files){if(-not $file){continue};if(-not $script:knownSources.Add($file.FullName)){$duplicates++;continue};$git=if($GitStatus.ContainsKey($file.FullName)){$GitStatus[$file.FullName]}else{$null};$item=New-DeliveryItem $file $RepoPath.Text.Trim() $true $git;$item.Status=Convert-UiStatus $item.Status;$item|Add-Member NoteProperty FileName ([IO.Path]::GetFileName($file.FullName));$item|Add-Member NoteProperty SourceFolder (Split-Path $file.FullName -Parent);$item|Add-Member NoteProperty FileType (Get-FileType $file.FullName);[void]$script:items.Add($item);$added++}
 Update-Ui;return [pscustomobject]@{Added=$added;Duplicates=$duplicates}
}
function Add-DirectPaths([string[]]$Paths,[hashtable]$GitStatus=@{}) {
 $files=New-Object System.Collections.Generic.List[object];foreach($path in $Paths){if(Test-Path -LiteralPath $path -PathType Leaf){$f=Get-Item -LiteralPath $path;if(-not(Test-DeliveryExcludedPath $f.FullName $ExcludeRules.Text)){[void]$files.Add($f)}}elseif(Test-Path -LiteralPath $path -PathType Container){Start-FolderScan @($path) $GitStatus}}
 if($files.Count){return Add-Items -Files @($files.ToArray()) -GitStatus $GitStatus};return [pscustomobject]@{Added=0;Duplicates=0}
}
function Start-FolderScan([string[]]$Paths,[hashtable]$GitStatus=@{}) {
 $ChooseFilesButton.IsEnabled=$false;$ChooseFolderButton.IsEnabled=$false;$CollectProgress.Visibility='Visible';$CollectHint.Text='Scanning files...';Set-Status 'Scanning files...';$script:scanGit=$GitStatus
 $script:scanJob=Start-Job -ArgumentList (Join-Path $script:appRoot 'Core.FileOps.ps1'),$Paths,$ExcludeRules.Text -ScriptBlock {param($m,$p,$rules);. $m;Get-DeliveryFiles -Paths $p -ExcludeRules $rules}
 $script:scanTimer=New-Object Windows.Threading.DispatcherTimer;$script:scanTimer.Interval=[TimeSpan]::FromMilliseconds(150);$script:scanTimer.Add_Tick({if($script:scanJob.State -notin @('Completed','Failed','Stopped')){return};$script:scanTimer.Stop();$ChooseFilesButton.IsEnabled=$true;$ChooseFolderButton.IsEnabled=$true;$CollectProgress.Visibility='Collapsed';if($script:scanJob.State -ne 'Completed'){Set-Status 'File scan failed. Choose the folder again.' '#B42318';return};$files=@(Receive-Job $script:scanJob);Remove-Job $script:scanJob -Force;$r=Add-Items -Files $files -GitStatus $script:scanGit;$CollectHint.Text="Added $($r.Added) file.";Set-Status "Added $($r.Added) file" '#16794A';if($r.Added){Set-Step 2}});$script:scanTimer.Start()
}
function Add-PastedPaths {
 $valid=New-Object System.Collections.Generic.List[string];$invalid=New-Object System.Collections.Generic.List[string];foreach($line in ($PasteInput.Text -split "`r?`n")){$value=$line.Trim().Trim('"');if(-not $value){continue};if($value.Contains("`t")){$value=@($value -split "`t"|Where-Object {$_.Trim()}|Select-Object -Last 1).Trim()};if(-not [IO.Path]::IsPathRooted($value)){$base=if($RepoPath.Text.Trim()){$RepoPath.Text.Trim()}else{''};if($base){$value=Join-Path $base $value}};if(Test-Path -LiteralPath $value){[void]$valid.Add($value)}else{[void]$invalid.Add($value)}}
 $r=Add-DirectPaths @($valid);$PasteResult.Text="Added $($r.Added) file | $($invalid.Count) invalid paths";if($r.Added){$PasteInput.Clear();Set-Status "Added $($r.Added) file" '#16794A';Set-Step 2}
}
function Show-SqlDialog {
 [xml]$dx='<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Configure SQL*Plus" Width="500" Height="330" ResizeMode="NoResize" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI"><Grid Margin="24"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="12"/><RowDefinition Height="Auto"/><RowDefinition Height="12"/><RowDefinition Height="Auto"/><RowDefinition Height="12"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBlock Text="Configure SQL*Plus" FontSize="18" FontWeight="SemiBold"/><StackPanel Grid.Row="2"><TextBlock Text="DB user"/><TextBox x:Name="User" Height="34" Margin="0,4,0,0" TabIndex="1"/></StackPanel><StackPanel Grid.Row="4"><TextBlock Text="Password (memory only)"/><PasswordBox x:Name="Password" Height="34" Margin="0,4,0,0" TabIndex="2"/></StackPanel><StackPanel Grid.Row="6"><TextBlock Text="TNS name"/><TextBox x:Name="Tns" Height="34" Margin="0,4,0,0" TabIndex="3"/></StackPanel><TextBlock x:Name="DialogError" Grid.Row="7" Foreground="#B42318" Visibility="Collapsed"/><TextBlock Grid.Row="7" Text="Password is kept in memory only. The script never stores it." Margin="0,12,0,0" Foreground="#5D6B7E"/><StackPanel Grid.Row="8" Orientation="Horizontal" HorizontalAlignment="Right"><Button x:Name="Cancel" Content="Cancel" IsCancel="True" Margin="0,0,8,0"/><Button x:Name="Save" Content="Save for this session" IsDefault="True"/></StackPanel></Grid></Window>'
 $d=[Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $dx));$d.Owner=$window;$u=$d.FindName('User');$p=$d.FindName('Password');$t=$d.FindName('Tns');$u.Text=$script:db.User;$p.Password=$script:db.Password;$t.Text=$script:db.Tns;$err=$d.FindName('DialogError');$d.FindName('Save').Add_Click({if(-not $u.Text.Trim()){$err.Text='DB user is required.';$err.Visibility='Visible';return};if(-not $t.Text.Trim()){$err.Text='TNS name is required.';$err.Visibility='Visible';return};$script:db.User=$u.Text.Trim();$script:db.Password=$p.Password;$script:db.Tns=$t.Text.Trim();$d.DialogResult=$true});[void]$d.ShowDialog()
}
function Start-Delivery {
 $selected=@(Get-SelectedItems);$dest=$DestinationPath.Text.Trim();if(-not(Test-Path -LiteralPath $dest -PathType Container)){$DestinationError.Text='Destination folder is invalid. Choose it again.';$DestinationError.Visibility='Visible';return};$DestinationError.Visibility='Collapsed'
 $mode=@('Skip','Overwrite','Rename automatically')[$DuplicateMode.SelectedIndex];if($mode -eq 'Overwrite'){$count=@($selected|Where-Object {Test-Path -LiteralPath (Join-Path $dest $_.Relative)}).Count;if($count -and [Windows.MessageBox]::Show("There are $count existing destination files. Overwrite them?",'Confirm overwrite',[Windows.MessageBoxButton]::YesNo,[Windows.MessageBoxImage]::Warning) -ne 'Yes'){return}}
 $DeliveryOptions.IsEnabled=$false;$StartDeliveryButton.IsEnabled=$false;$CancelDeliveryButton.IsEnabled=$true;$DeliveryProgress.Maximum=$selected.Count;$script:cancelFile=Join-Path ([IO.Path]::GetTempPath())('delivery-copy-'+[Guid]::NewGuid()+'.cancel');$jobItems=@($selected|ForEach-Object {[pscustomobject]@{Included=$_.Included;Source=$_.Source;Relative=$_.Relative;ActualDestination=$null;Size=$_.Size;SizeDisplay=$_.SizeDisplay;Status=$_.Status;StatusBrush=$_.StatusBrush}});$verify=[bool]$VerifyHash.IsChecked;$run=[bool]$CreateRunScript.IsChecked;$SqlConfigError.Visibility='Collapsed';if($run){$missing=@();if(-not $script:db.User.Trim()){$missing+='DB user'};if(-not $script:db.Tns.Trim()){$missing+='TNS name'};if($missing.Count){$SqlConfigError.Text='SQL*Plus is not configured (missing: '+($missing -join ', ')+'). Click Configure SQL*Plus.';$SqlConfigError.Visibility='Visible';return}}
 $script:copyJob=Start-Job -ArgumentList (Join-Path $script:appRoot 'Core.FileOps.ps1'),(Join-Path $script:appRoot 'Core.SqlPlus.ps1'),$jobItems,$dest,$mode,$verify,$run,$script:db.User,$script:db.Tns,$script:db.Log,$script:cancelFile -ScriptBlock {param($fm,$sm,$items,$d,$mode,$verify,$run,$u,$t,$log,$cancel);. $fm;. $sm;$report={param($done,$total,$message)Write-Progress -Activity 'Delivery' -Status $message -PercentComplete ([int](($done/[Math]::Max($total,1))*100))};$stop={Test-Path -LiteralPath $cancel};$result=Copy-DeliveryFiles -Items $items -Destination $d -DuplicateMode $mode -VerifyHash $verify -ReportProgress $report -IsCancelled $stop;if($run -and -not $result.Cancelled){$result|Add-Member NoteProperty RunScriptPath (New-DeliveryRunScript -Items $items -Destination $d -DbUser $u -TnsName $t -LogFile $log)};$result}
 $script:copyTimer=New-Object Windows.Threading.DispatcherTimer
 $script:copyTimer.Interval=[TimeSpan]::FromMilliseconds(200)
 $script:copyTimer.Add_Tick({
  $p=@($script:copyJob.ChildJobs[0].Progress|Select-Object -Last 1)
  if($p.Count){$DeliveryProgress.Value=[Math]::Round(($p[0].PercentComplete/100)*$DeliveryProgress.Maximum);$DeliveryStatus.Text=$p[0].StatusDescription;Set-Status "Delivering $([int]$DeliveryProgress.Value)/$([int]$DeliveryProgress.Maximum) file"}
  if($script:copyJob.State -notin @('Completed','Failed','Stopped')){return}
  $script:copyTimer.Stop();$DeliveryOptions.IsEnabled=$true;$CancelDeliveryButton.IsEnabled=$false
  if($script:copyJob.State -ne 'Completed'){$DeliveryStatus.Text='Delivery failed.';Set-Status 'Delivery failed.' '#B42318';return}
  $result=@(Receive-Job $script:copyJob|Select-Object -Last 1)[0];Remove-Job $script:copyJob -Force
  if(Test-Path $script:cancelFile){Remove-Item $script:cancelFile -Force}
  $map=@{};foreach($x in $result.Items){$map[$x.Source]=$x};foreach($item in $script:items){if($map.ContainsKey($item.Source)){$item.ActualDestination=$map[$item.Source].ActualDestination;$item.Status=Convert-UiStatus $map[$item.Source].Status;$item.StatusBrush=$map[$item.Source].StatusBrush}}
  Update-Ui;$m=Import-Csv $result.ManifestPath;$copied=@($m|Where-Object Result -eq 'Copied').Count;$skipped=@($m|Where-Object Result -eq 'Skipped').Count;$failed=@($m|Where-Object {$_.Result -eq 'Failed'}).Count
  $ResultTitle.Text=if($failed){'Delivery completed with errors'}elseif($result.Cancelled){'Delivery cancelled'}else{'Delivery completed'}
  $resultColor=if($failed){'#B42318'}elseif($result.Cancelled){'#A96500'}else{'#16794A'}
  $ResultTitle.Foreground=[Windows.Media.BrushConverter]::new().ConvertFromString($resultColor)
  $ResultSummary.Text="$copied copied | $skipped skipped | $failed failed";$script:manifestPath=$result.ManifestPath;$ResultPanel.Visibility='Visible';$OpenDestinationButton.IsEnabled=$true;$ReviewErrorsButton.Visibility=if($failed){'Visible'}else{'Collapsed'};Set-Status $ResultTitle.Text $resultColor
 })
 $script:copyTimer.Start()
}
$ChooseFilesButton.Add_Click({$d=New-Object Windows.Forms.OpenFileDialog;$d.Multiselect=$true;if($d.ShowDialog() -eq 'OK'){$r=Add-DirectPaths @($d.FileNames);$CollectHint.Text="Added $($r.Added) file.";Set-Status "Added $($r.Added) file" '#16794A';if($r.Added){Set-Step 2}}})
$ChooseFolderButton.Add_Click({$d=New-Object Windows.Forms.FolderBrowserDialog;if($d.ShowDialog() -eq 'OK'){Start-FolderScan @($d.SelectedPath)}})
$AddPathsButton.Add_Click({Add-PastedPaths})
$ChooseRepoButton.Add_Click({$d=New-Object Windows.Forms.FolderBrowserDialog;if($d.ShowDialog() -eq 'OK'){$RepoPath.Text=$d.SelectedPath;$GitHint.Text='Load branches to choose a base and compare branch.'}})
$LoadBranchesButton.Add_Click({try{$repo=Get-DeliveryGitRoot $RepoPath.Text;$RepoPath.Text=$repo;$branches=Get-DeliveryGitBranches $repo;$BaseBranch.ItemsSource=$branches;$CompareBranch.ItemsSource=$branches;$BaseBranch.IsEnabled=$true;$CompareBranch.IsEnabled=$true;$AddGitChangesButton.IsEnabled=$true;$current=@(Invoke-DeliveryGit $repo @('branch','--show-current'))[0];$BaseBranch.Text=if($branches -contains 'main'){'main'}elseif($branches -contains 'master'){'master'}else{$current};$CompareBranch.Text=$current;$GitHint.Text="Loaded $($branches.Count) branches."}catch{$GitHint.Text='Could not load branches. Choose the repository folder again.'}})
$AddGitChangesButton.Add_Click({try{$repo=Get-DeliveryGitRoot $RepoPath.Text;$c=Get-DeliveryGitChanges $repo $BaseBranch.Text.Trim() $CompareBranch.Text.Trim() ([bool]$IncludeWorkspace.IsChecked);$files=@($c.Changes.Keys|Where-Object {Test-Path $_ -PathType Leaf}|ForEach-Object {Get-Item $_});$r=Add-Items -Files $files -GitStatus $c.Changes;Set-Status "Added $($r.Added) file(s) from Git" '#16794A';if($r.Added){Set-Step 2}}catch{$GitHint.Text='Could not compare changes. Check the selected branches.'}})
$SearchBox.Add_TextChanged({Refresh-Grid});$FilterBox.Add_SelectionChanged({Refresh-Grid});$FileGrid.Add_CurrentCellChanged({$window.Dispatcher.BeginInvoke([Action]{Update-Ui},[Windows.Threading.DispatcherPriority]::Background)|Out-Null})
$ToggleFilteredButton.Add_Click({$targets=@($script:viewItems);if($targets.Count -gt 100 -and [Windows.MessageBox]::Show("Change selection for $($targets.Count) filtered files?",'Confirm',[Windows.MessageBoxButton]::YesNo) -ne 'Yes'){return};$check=@($targets|Where-Object {-not $_.Included}).Count -gt 0;foreach($i in $targets){$i.Included=$check};Update-Ui})
$SelectAllButton.Add_Click({foreach($i in $script:items){$i.Included=$true};Update-Ui});$ClearSelectionButton.Add_Click({foreach($i in $script:items){$i.Included=$false};Update-Ui})
$RemoveSelectedButton.Add_Click({$targets=@($script:items|Where-Object Included);if(-not $targets.Count){return};if([Windows.MessageBox]::Show("Remove $($targets.Count) files from the list? Original files are not deleted.",'Confirm removal',[Windows.MessageBoxButton]::YesNo,[Windows.MessageBoxImage]::Warning) -ne 'Yes'){return};foreach($i in $targets){$script:knownSources.Remove($i.Source)|Out-Null;$script:items.Remove($i)};Update-Ui})
$Step1Button.Add_Click({Set-Step 1});$Step2Button.Add_Click({if($Step2Button.IsEnabled){Set-Step 2}});$Step3Button.Add_Click({if($Step3Button.IsEnabled){Set-Step 3}});$ContinueButton.Add_Click({if($Step3Button.IsEnabled){Set-Step 3}});$BackToReviewButton.Add_Click({Set-Step 2})
$ChooseDestinationButton.Add_Click({$d=New-Object Windows.Forms.FolderBrowserDialog;if($d.ShowDialog() -eq 'OK'){$DestinationPath.Text=$d.SelectedPath;$DestinationError.Visibility='Collapsed'}});$ConfigureSqlButton.Add_Click({Show-SqlDialog});$CreateRunScript.Add_Checked({$SqlSettingsLine.Visibility='Visible'});$CreateRunScript.Add_Unchecked({$SqlSettingsLine.Visibility='Collapsed'});$StartDeliveryButton.Add_Click({Start-Delivery});$CancelDeliveryButton.Add_Click({if($script:copyJob){New-Item -ItemType File -Path $script:cancelFile -Force|Out-Null;$CancelDeliveryButton.IsEnabled=$false;$DeliveryStatus.Text='Cancelling after the current file...'}});$OpenDestinationButton.Add_Click({if(Test-Path $DestinationPath.Text){Start-Process explorer.exe -ArgumentList ('"'+$DestinationPath.Text+'"')}});$OpenManifestButton.Add_Click({if(Test-Path $script:manifestPath){Start-Process $script:manifestPath}});$ReviewErrorsButton.Add_Click({$FilterBox.SelectedIndex=4;Set-Step 2})
Update-Ui;Set-Step 1;if(-not $NoShow){[void]$window.ShowDialog()}
